// === ESTRUCTURA DEL PATRÓN STRATEGY ===

// 1. Interfaz Strategy (el contrato)
interface PaymentStrategy {
  pay(amount: number): PaymentResult;
}

// 2. Estrategias Concretas (las variantes)
class CreditCardStrategy implements PaymentStrategy {
  constructor(private cardNumber: string) {}

  pay(amount: number): PaymentResult {
    // Lógica específica de pago con tarjeta
    return { success: true, transactionId: 'tx_123' };
  }
}

class PayPalStrategy implements PaymentStrategy {
  constructor(private email: string) {}

  pay(amount: number): PaymentResult {
    // Lógica específica de pago con PayPal
    return { success: true, transactionId: 'tx_456' };
  }
}

class CryptoStrategy implements PaymentStrategy {
  pay(amount: number): PaymentResult {
    // Lógica específica de pago con cripto
    return { success: true, transactionId: 'tx_789' };
  }
}

// 3. Contexto (usa la estrategia sin conocer detalles)
class Checkout {
  constructor(private strategy: PaymentStrategy) {}

  setStrategy(strategy: PaymentStrategy) {
    this.strategy = strategy;
  }

  processOrder(amount: number) {
    return this.strategy.pay(amount);
  }
}

// Uso:
const checkout = new Checkout(new CreditCardStrategy('4111-1111-1111-1111'));
checkout.processOrder(100);
checkout.setStrategy(new PayPalStrategy('user@example.com'));
checkout.processOrder(200);

