// 1. Interfaz común
interface RouteStrategy {
  buildRoute(A: Point, B: Point): Route;
}

// 2. Estrategias concretas aisladas
class CarStrategy implements RouteStrategy {
  buildRoute(A: Point, B: Point) { /* ... */ }
}

// 3. El Contexto usa la interfaz
class Navigator {
  private strategy: RouteStrategy;
  setStrategy(s: RouteStrategy) { this.strategy = s; }
  buildRoute(A: Point, B: Point) {
    return this.strategy.buildRoute(A, B);
  }
}

